/* ddl_schemas_e_chaves: */
CREATE SCHEMA IF NOT EXISTS "hidro";
CREATE SCHEMA IF NOT EXISTS "geo";

CREATE TABLE "hidro"."estacao" (
    "id" INTEGER PRIMARY KEY,
    "codigo" VARCHAR(20) NOT NULL UNIQUE,
    "nome" VARCHAR(80) NOT NULL DEFAULT 'sem nome',
    "ativo" BOOLEAN DEFAULT true,
    "criado" TIMESTAMP DEFAULT now()
);

ALTER TABLE "hidro"."estacao" ADD CONSTRAINT "ck_nome" CHECK (length(nome) > 2);

ALTER TABLE "hidro"."estacao" ADD CHECK (id > 0);

CREATE TABLE "geo"."municipio" (
    "uf" CHAR(2),
    "cod" INTEGER,
    "nome" VARCHAR(60),
    PRIMARY KEY (uf, cod),
    UNIQUE (uf, nome)
);

CREATE TABLE "hidro"."medicao" (
    "id" BIGINT,
    "estacao_id" INTEGER NOT NULL,
    "uf" CHAR(2),
    "cod" INTEGER,
    "valor" NUMERIC(10,2) DEFAULT 0
);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "pk_medicao" PRIMARY KEY (id);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "uq_medicao" UNIQUE (estacao_id, valor);

CREATE TABLE "avulsa" (
    "id" INTEGER,
    "ref" INTEGER,
    "x" INTEGER
);

ALTER TABLE "avulsa" ADD CONSTRAINT "pk_avulsa" PRIMARY KEY (id);

ALTER TABLE "avulsa" ADD CONSTRAINT "uq_avulsa_x" UNIQUE (x);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "fk_med_est"
    FOREIGN KEY (estacao_id)
    REFERENCES "hidro"."estacao" (id);

ALTER TABLE "hidro"."medicao" ADD CONSTRAINT "FK_medicao_4"
    FOREIGN KEY (uf, cod)
    REFERENCES "geo"."municipio" (uf, cod);

ALTER TABLE "avulsa" ADD CONSTRAINT "FK_avulsa_3"
    FOREIGN KEY (ref)
    REFERENCES "avulsa" (id);

